+                        // the rework leg pushes a new (clean) head — the PR
+                        // re-enters through the normal re-arm path.
+                        s.redPending = false;
+                        s.phase = 'refresh';
+                        s.refreshed = now + REFRESH_TICKS * TICK_MIN;
+                        redReports++;
+                    } else {
+                        s.phase = 'green';
+                    }
