+                JSON.stringify(jsonVal));
+        }
+        return null;
+    }
+    var max = pick(jobParams && jobParams.validationConcurrency,
+        projectCfg && projectCfg.smValidationConcurrency, 'smValidationConcurrency');
+    if (max) {
