            key: 'pr-' + p.number,
            labels: prLabels(p),
            pr: null,
            issueNumber: linkedIssueNumber(p.body),
            prNumber: p.number,
            draft: !!p.draft,
            branch: (p.head && p.head.ref) || p.headRefName || '',
            title: p.title || '',
