+            '../../common/machineAuthor.js': loadModule('js/common/machineAuthor.js', makeRequire({}), {}),
+            '../../common/smProvider.js': { createSmProvider: function () { return providerStub; } },
+            '../../common/smAsync.js': smAsyncMod
