+        function publish() {
+            var open = [], statuses = {};
+            prNumbers.forEach(function (n) {
+                var s = st[n];
+                if (s.phase === 'merged') return; // merged PRs leave the open list
+                var labels = [{ name: 'pr_approved' }];
