+        // Repo variables arrive as strings — accept the '5' form too.
+        if (typeof jsonVal === 'string') jsonVal = parseInt(jsonVal, 10);
+        if (typeof cfgVal === 'string') cfgVal = parseInt(cfgVal, 10);
