+            serial.toFixed(0) + ' (' + r.intervals + ')');
+        console.log('gh-837 sim: serial ' + serial.toFixed(0) + ' min/merge, parallel-2 ' +
+            a.toFixed(0) + ' min/merge, intervals ' + JSON.stringify(r.intervals));
